#include <iostream>
#include <sstream>
#include <string>

int main()
{
    // String length: "100 Jones 24.98\n" -> 17 characters (bytes)
    std::string data = "100 Jones 24.98\n200 Doe 345.67\n";
    std::istringstream stream(data);

    std::cout << "Start position: " << stream.tellg() << "\n";

    int account;
    std::string name;
    double balance;

    if (stream >> account >> name >> balance)
    {
        std::cout << "Read: " << account << " " << name << " " << balance << "\n";
    }

    std::cout << "Position after first record: " << stream.tellg() << "\n";

    // Reposition back to beginning
    stream.seekg(0, std::ios::beg);
    std::cout << "Position after seekg(0): " << stream.tellg() << "\n";

    if (stream >> account >> name >> balance)
    {
        std::cout << "Re-read: " << account << " " << name << " " << balance << "\n";
    }

    return 0;
}

#include <iostream>
#include <sstream>
#include <iomanip>

enum RequestType { ZERO_BALANCE = 1, CREDIT_BALANCE, DEBIT_BALANCE, END };

bool shouldDisplay(int type, double balance)
{
    if (type == ZERO_BALANCE && balance == 0.0)
        return true;
    if (type == CREDIT_BALANCE && balance < 0.0)
        return true;
    if (type == DEBIT_BALANCE && balance > 0.0)
        return true;
    return false;
}

void outputLine(int account, const std::string &name, double balance)
{
    std::cout << std::left << std::setw(10) << account
              << std::setw(13) << name
              << std::setw(7) << std::setprecision(2) << std::fixed << std::right
              << balance << "\n";
}

int main()
{
    std::string fileContent =
        "100 Jones 24.98\n"
        "200 Doe 345.67\n"
        "300 White 0.00\n"
        "400 Stone -42.16\n"
        "500 Rich 224.62\n";

    std::istringstream inClientFile(fileContent);

    // Simulated sequence of requests: 1 (zero), 2 (credit), 4 (end)
    int requests[] = { ZERO_BALANCE, CREDIT_BALANCE, END };

    for (int request : requests)
    {
        if (request == END)
            break;

        if (request == ZERO_BALANCE)
            std::cout << "\nAccounts with zero balances:\n";
        else if (request == CREDIT_BALANCE)
            std::cout << "\nAccounts with credit balances:\n";
        else if (request == DEBIT_BALANCE)
            std::cout << "\nAccounts with debit balances:\n";

        int account;
        std::string name;
        double balance;

        while (inClientFile >> account >> name >> balance)
        {
            if (shouldDisplay(request, balance))
                outputLine(account, name, balance);
        }

        // Reset EOF flags and rewind to file beginning
        inClientFile.clear();
        inClientFile.seekg(0);
    }

    std::cout << "End of run.\n";
    return 0;
}
